package main
import("encoding/json";"net/http";"strings";"github.com/jackc/pgx/v5/pgxpool")
type branchInput struct{Name string `json:"name"`;Code string `json:"code"`;Address string `json:"address"`;Phone string `json:"phone"`;Email string `json:"email"`}
func createBranch(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){var x branchInput;if json.NewDecoder(r.Body).Decode(&x)!=nil||strings.TrimSpace(x.Name)==""||strings.TrimSpace(x.Code)==""{http.Error(w,"branch name and code are required",400);return};c:=claimsFrom(r);var id string;err:=db.QueryRow(r.Context(),`INSERT INTO branches(tenant_id,name,code,address,phone,email)VALUES($1,$2,upper($3),NULLIF($4,''),NULLIF($5,''),NULLIF(lower($6),''))RETURNING id`,c.Tenant,strings.TrimSpace(x.Name),strings.TrimSpace(x.Code),strings.TrimSpace(x.Address),strings.TrimSpace(x.Phone),strings.TrimSpace(x.Email)).Scan(&id);if err!=nil{http.Error(w,"branch code already exists",409);return};auditUserAction(r,db,"BRANCH_CREATED",id,x);w.WriteHeader(201);json.NewEncoder(w).Encode(map[string]string{"id":id})}}
func updateBranch(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){var x branchInput;if json.NewDecoder(r.Body).Decode(&x)!=nil||strings.TrimSpace(x.Name)==""||strings.TrimSpace(x.Code)==""{http.Error(w,"branch name and code are required",400);return};tag,err:=db.Exec(r.Context(),`UPDATE branches SET name=$3,code=upper($4),address=NULLIF($5,''),phone=NULLIF($6,''),email=NULLIF(lower($7),''),updated_at=now() WHERE id=$1 AND tenant_id=$2`,r.PathValue("id"),claimsFrom(r).Tenant,strings.TrimSpace(x.Name),strings.TrimSpace(x.Code),strings.TrimSpace(x.Address),strings.TrimSpace(x.Phone),strings.TrimSpace(x.Email));if err!=nil||tag.RowsAffected()!=1{http.Error(w,"branch not found or code duplicated",409);return};auditUserAction(r,db,"BRANCH_UPDATED",r.PathValue("id"),x);w.WriteHeader(204)}}
func branchStatus(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){var x struct{Active bool `json:"active"`};if json.NewDecoder(r.Body).Decode(&x)!=nil{http.Error(w,"active status required",400);return};c:=claimsFrom(r);if !x.Active{var activeUsers int;_ = db.QueryRow(r.Context(),`SELECT count(*) FROM users WHERE tenant_id=$1 AND branch_id=$2 AND is_active AND deleted_at IS NULL`,c.Tenant,r.PathValue("id")).Scan(&activeUsers);if activeUsers>0{http.Error(w,"move or deactivate active branch users first",409);return}};tag,err:=db.Exec(r.Context(),`UPDATE branches SET is_active=$3,updated_at=now() WHERE id=$1 AND tenant_id=$2`,r.PathValue("id"),c.Tenant,x.Active);if err!=nil||tag.RowsAffected()!=1{http.Error(w,"branch not found",404);return};auditUserAction(r,db,"BRANCH_STATUS_CHANGED",r.PathValue("id"),x);w.WriteHeader(204)}}
